public class IndexOfMin {

    public static int indexOfMin(int[] values) {
        if (values.length == 0) {
            return -1;
        }
        int minIndex = 0;
        for (int i = 1; i < values.length; i++) {
            if (values[i] < values[minIndex]) {
                minIndex = i;
            }
        }
        return minIndex;
    }
}
